/**
 * The cart as a page: the lines as cards (picture, name, variant, price, quantity, line total, remove) with the
 * way back, beside the order summary with a promo code and the free-delivery bar. Static markup. Axes: layout
 * (split: the summary beside the lines, stacked: below them), promo (show, hide), progress (show, hide), tone.
 */
import { type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Button } from "../primitives/button/button";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { CartSummaryCard } from "../components/cart-summary-card";
import { MediaFrame } from "../components/media-frame";
import { NumberField } from "../components/number-field";
import { SectionFrame } from "../components/section-frame";
import { fmtMoney, tpl } from "../utils";
import type { ShoppingCartLabels } from "./shopping-cart.types";
import type { CartLine, CartLabels } from "./cart-list.types";
import type { SummaryRow } from "./order-summary.types";
import type { Promo, CartSummaryLabels } from "../components/cart-summary-card.types";

export type ShoppingCartProps = {
  id: string;
  title: string;
  lines: CartLine[];
  rows: SummaryRow[];
  promos: Promo[];
  labels: CartLabels;
  totals: CartSummaryLabels;
  actions: ShoppingCartLabels;
  layout?: "split" | "stacked";
  promo?: "show" | "hide";
  progress?: "show" | "hide";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function ShoppingCart({
  id,
  title,
  lines,
  rows,
  promos,
  labels,
  totals,
  actions,
  layout = "split",
  promo = "show",
  progress = "show",
  tone = "default",
  landmarkLabel,
}: ShoppingCartProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} landmarkLabel={landmarkLabel}>
      <Box
        className={
          (layout as string) === "split" ? "grid grid-cols-1 items-start gap-8 lg:grid-cols-3"
          : "grid grid-cols-1 gap-8"
        }
      >
        <Stack
          gap="4"
          align="stretch"
          className={(((layout as string) === "split") ? "lg:col-span-2" : "")}
          data-testid="lines"
        >
          {(lines ?? []).map((line) => (
            <Group key={line.id}
              gap="4"
              align="center"
              className="rounded bg-card inset-ring inset-ring-border flex-wrap p-4"
              data-testid="item"
            >
              <MediaFrame alt={line.name} ratio="1/1" className="size-20 shrink-0" />
              <Stack gap="0" className="min-w-40 flex-1">
                <Text size="sm" weight="semibold">
                  {line.name}
                </Text>
                <Text size="xs" className="text-muted-foreground">
                  {line.variant}
                </Text>
                <Text size="sm">
                  {fmtMoney(line.price, line.currency)}
                </Text>
              </Stack>
              <NumberField
                value={(line.qty == null ? undefined : String(line.qty))}
                name={tpl("{0}-qty-{1}", id, line.id)}
                min="1"
                label={labels.qty}
                decrease={labels.decrease}
                increase={labels.increase}
              />
              <Text size="base" weight="bold" className="w-24 text-right">
                {fmtMoney((line.price * line.qty), line.currency)}
              </Text>
              <Button variant="ghost" size="sm" layout="icon" aria-label={labels.remove} data-testid="remove">
                <LucideIcon name="trash" size={16} />
              </Button>
            </Group>
          ))}
          <Group gap="4" justify="between" className="flex-wrap">
            <Button variant="outline" size="default">
              <LucideIcon name="arrow-left" size={16} />
              {actions.back}
            </Button>
            <Button variant="ghost" size="default">
              {actions.clear}
            </Button>
          </Group>
        </Stack>
        <Box className={(((layout as string) === "split") ? "lg:sticky lg:top-8" : "")} data-testid="aside">
          <CartSummaryCard
            field={tpl("{0}-promo", id)}
            lines={lines}
            rows={rows}
            promos={promos}
            labels={totals}
            promo={promo}
            progress={progress}
          />
        </Box>
      </Box>
    </SectionFrame>
  );
}

